window.createTToxNetworkPanel=function(root,{show,back,onSnapshot,radio=true}){
 const q=s=>root.querySelector(s),panel=q('.room-wifi'),N=window.TToxNetwork,adapter=N.createDemo({radio});
 const fields={ipv4:'net-ipv4',address:'net-address',gateway:'net-gateway',dns:'net-dns',ipv6:'net-ipv6',mtu:'net-mtu',mac:'net-mac',metered:'net-metered'};
 let selected='studio',tab='overview',snapshot=adapter.snapshot(),mode='balanced',open=false,poll=null,operation=null,operationId=0,busy=false,scanning=false,armed=null,armTimer=null,reviewDraft=null,checkpoint=null,revertTimer=null;
 const node=(tag,text)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;return e;};
 function message(text=''){q('#net-message').textContent=text;}
 function error(text=''){q('#net-error').textContent=text;q('#net-error').hidden=!text;}
 function wipeSecret(){q('#net-password').value='';q('#net-password').removeAttribute('aria-invalid');q('#net-password').type='password';q('#net-show-password').textContent='Show';q('#net-show-password').setAttribute('aria-pressed','false');q('#net-password-form').hidden=true;}
 function cancelOperation(){operationId++;operation?.abort();operation=null;busy=false;scanning=false;q('#net-scan').textContent='Scan networks';}
 function stopPoll(){if(poll)clearInterval(poll);poll=null;}
 function startPoll(){stopPoll();if(!open||document.hidden)return;const ms={full:1000,balanced:2000,lite:5000}[mode];q('#net-poll-label').textContent=(ms/1000)+'-second demo samples while open';poll=setInterval(()=>{snapshot=adapter.tick();renderMetrics();syncSummary();},ms);}
 function syncSummary(){onSnapshot?.(snapshot);}
 function resetArm(){armed=null;clearTimeout(armTimer);armTimer=null;q('#net-disconnect').textContent='Disconnect';q('#net-forget').textContent='Forget profile';}
 function confirm(action){const id=selected;if(armed?.action===action&&armed.id===id&&Date.now()<armed.until){resetArm();return true;}resetArm();armed={action,id,until:Date.now()+2000};q(action==='disconnect'?'#net-disconnect':'#net-forget').textContent='Confirm '+action;armTimer=setTimeout(resetArm,2000);message('Click again within 2 seconds to '+action+'.');return false;}
 function format(value){if(Array.isArray(value))return value.join(', ')||'—';if(typeof value==='boolean')return value?'On':'Off';return ({auto:'Automatic',manual:'Manual',disabled:'Disabled',stable:'Stable private',random:'Random',permanent:'Device address',yes:'Metered',no:'Unmetered'})[value]??String(value??'—');}
 function renderNetworks(){const target=q('#net-networks');target.replaceChildren();for(const n of snapshot.networks){const b=node('button');b.type='button';b.className='net-network-row';b.setAttribute('aria-pressed',n.id===selected);const label=node('span');label.append(node('b',n.ssid),node('small',(n.id===snapshot.active?'Connected · ':n.saved?'Saved · ':'')+n.security));b.append(label,node('span',n.signal+'%'));b.onclick=()=>choose(n.id);target.append(b);}q('#net-scan').disabled=!snapshot.radio||busy||scanning;q('#net-radio').checked=snapshot.radio;q('#net-connection-state').textContent=snapshot.radio?(snapshot.active?'Connected · demo':'Not connected · demo'):'Wi-Fi off · demo';}
 function path(data,max){if(!data.length)return '';const points=data.length===1?[data[0],data[0]]:data;return points.map((v,i)=>(i?'L':'M')+(i/(points.length-1)*500).toFixed(1)+','+(66-Number(v)/max*60).toFixed(1)).join(' ');}
 function renderMetrics(){const n=snapshot.networks.find(n=>n.id===selected),active=n?.id===snapshot.active,cfg=active?snapshot.profile:null,m=snapshot.metrics;if(!n)return;
  q('#net-ssid').textContent=n.ssid;q('#net-security').textContent=n.security+' · '+n.frequency+' MHz';q('#net-saved').hidden=!n.saved;q('#net-signal').textContent=n.signal+'% / '+n.rssi+' dBm';q('#net-rate').textContent=active?n.rate+' Mb/s':'—';q('#net-band').textContent=n.band+' / '+n.channel;
  q('#net-down').textContent=active?m.down+' KB/s':'—';q('#net-up').textContent=active?m.up+' KB/s':'—';q('#net-sample-label').textContent=active?'Demo replay · sample '+m.sample:'Connect to view traffic';
  const max=Math.max(1,...m.historyDown,...m.historyUp);q('#net-chart-range').textContent=active?'0–'+max+' KB/s · solid download / dashed upload · last '+m.historyDown.length+' samples':'No traffic for this network';q('#net-down-path').setAttribute('d',active?path(m.historyDown,max):'');q('#net-up-path').setAttribute('d',active?path(m.historyUp,max):'');
  const ip=active?snapshot.link.address:'—',dns=active?snapshot.link.dns.join(', '):'—';
  const details=[['Interface',snapshot.interface],['BSSID',n.bssid],['IPv4 address',ip],['Gateway',active?snapshot.link.gateway:'—'],['DNS servers',dns],['IPv6',active&&cfg.ipv6!=='disabled'?snapshot.link.ipv6:'—'],['Device MAC',snapshot.mac],['Session traffic',active?m.totalDown.toFixed(2)+' MB ↓ / '+m.totalUp.toFixed(2)+' MB ↑':'—'],['Latency',active?m.latency+' ms (demo)':'—']];const dl=q('#net-details');dl.replaceChildren();for(const[k,v]of details)dl.append(node('dt',k),node('dd',v));
  q('#net-scan').disabled=!snapshot.radio||busy||scanning;q('#net-password').disabled=busy;q('#net-show-password').disabled=busy;q('#net-password-submit').disabled=busy;q('#net-connect').hidden=active;q('#net-connect').disabled=!snapshot.radio||busy;q('#net-connect').textContent=busy?'Connecting…':'Connect';q('#net-disconnect').hidden=!active;q('#net-disconnect').disabled=busy;q('#net-forget').hidden=!n.saved;q('#net-forget').disabled=busy;
 }
 function editable(){return selected===snapshot.active&&snapshot.radio&&!busy&&!checkpoint;}
 function syncFields(){const edit=editable();for(const e of q('#net-settings-form').querySelectorAll('input,select,button'))e.disabled=!edit;q('#net-address').disabled=!edit||q('#net-ipv4').value!=='manual';q('#net-gateway').disabled=!edit||q('#net-ipv4').value!=='manual';q('#net-dns').disabled=!edit||q('#net-dns-auto').checked;q('#net-settings-help').textContent=selected===snapshot.active?'Changes affect the demo profile only. Review before applying.':'Connect to this network before editing its profile.';}
 function fillForm(){const c=selected===snapshot.active?snapshot.profile:null;for(const[key,id]of Object.entries(fields))q('#'+id).value=key==='dns'?(c?.dns||[]).join(', '):c?.[key]??({ipv4:'auto',ipv6:'auto',mtu:0,mac:'stable',metered:'auto'})[key]??'';q('#net-dns-auto').checked=c?.dnsAuto??true;q('#net-autoconnect').checked=c?.autoconnect??true;for(const e of q('#net-settings-form').querySelectorAll('[aria-invalid]'))e.removeAttribute('aria-invalid');syncFields();}
 function render(full=true){renderNetworks();renderMetrics();syncSummary();if(full)fillForm();}
 function setTab(value){tab=value;q('#net-overview').hidden=value!=='overview';q('#net-settings').hidden=value!=='settings';q('#net-overview-tab').setAttribute('aria-pressed',value==='overview');q('#net-settings-tab').setAttribute('aria-pressed',value==='settings');}
 function clearReview(){reviewDraft=null;q('#net-review').hidden=true;q('#net-settings-form').hidden=false;}
 function rollback(text){if(!checkpoint)return;clearInterval(revertTimer);revertTimer=null;snapshot=adapter.restore(checkpoint.id,checkpoint.before);checkpoint=null;q('#net-checkpoint').hidden=true;q('#net-settings-form').hidden=false;render();message(text||'Previous demo settings restored.');}
 function choose(id){rollback('Unconfirmed changes reverted.');cancelOperation();wipeSecret();resetArm();clearReview();selected=id;error();message();q('#net-diagnostic-output').hidden=true;render();}
 async function connect(secret=''){cancelOperation();operation=new AbortController();const ticket=operationId,id=selected;busy=true;error();message('Connecting to the sample access point…');renderMetrics();syncFields();let request;
  try{request=adapter.connect(id,secret,operation.signal);secret='';await request;if(ticket!==operationId)return;snapshot=adapter.snapshot();selected=id;wipeSecret();clearReview();render();message('Connected in demo. No device settings were changed.');}
  catch(e){if(ticket===operationId&&e.name!=='AbortError')error(e.message);}
  finally{secret='';if(ticket===operationId){busy=false;operation=null;renderMetrics();syncFields();}}
 }
 function readDraft(){const draft={};for(const[key,id]of Object.entries(fields))draft[key]=q('#'+id).value;draft.dnsAuto=q('#net-dns-auto').checked;draft.autoconnect=q('#net-autoconnect').checked;return draft;}
 q('#net-back').onclick=()=>{api.onClose();back();};q('#net-radio').onchange=e=>{rollback();cancelOperation();wipeSecret();snapshot=adapter.setRadio(e.target.checked);clearReview();render();message(snapshot.radio?'Select a network to connect.':'Wi-Fi disabled in demo.');};
 q('#net-scan').onclick=async()=>{cancelOperation();operation=new AbortController();const ticket=operationId;scanning=true;q('#net-scan').disabled=true;q('#net-scan').textContent='Scanning…';error();try{await adapter.scan(operation.signal);if(ticket===operationId){snapshot=adapter.snapshot();renderNetworks();message('Sample network list refreshed.');}}catch(e){if(ticket===operationId&&e.name!=='AbortError')error(e.message);}finally{if(ticket===operationId){scanning=false;q('#net-scan').textContent='Scan networks';renderMetrics();}}};
 q('#net-overview-tab').onclick=()=>setTab('overview');q('#net-settings-tab').onclick=()=>{setTab('settings');syncFields();};
 q('#net-connect').onclick=()=>{error();const n=snapshot.networks.find(n=>n.id===selected);if(n.security!=='Open'&&!n.saved){q('#net-password-form').hidden=false;q('#net-password').focus();}else connect();};
 q('#net-password-form').onsubmit=e=>{e.preventDefault();const value=q('#net-password').value,invalid=N.validatePassphrase(value);if(invalid){error(invalid);q('#net-password').setAttribute('aria-invalid','true');return;}q('#net-password').removeAttribute('aria-invalid');connect(value);q('#net-password').value='';};
 q('#net-password-cancel').onclick=()=>{cancelOperation();wipeSecret();error();message('Connection cancelled.');renderMetrics();};q('#net-show-password').onclick=()=>{const input=q('#net-password'),show=input.type==='password';input.type=show?'text':'password';q('#net-show-password').textContent=show?'Hide':'Show';q('#net-show-password').setAttribute('aria-pressed',show);};
 q('#net-disconnect').onclick=()=>{if(!confirm('disconnect'))return;rollback();cancelOperation();snapshot=adapter.disconnect();render();message('Disconnected in demo.');};
 q('#net-forget').onclick=()=>{if(!confirm('forget'))return;rollback();cancelOperation();wipeSecret();snapshot=adapter.forget(selected);render();message('Demo profile forgotten. No stored password exists in this preview.');};
 q('#net-diagnostics').onclick=()=>{const box=q('#net-diagnostic-output');box.replaceChildren();for(const[k,v]of adapter.diagnostics())box.append(node('div',k+' / '+v));box.hidden=false;};
 q('#net-ipv4').onchange=syncFields;q('#net-dns-auto').onchange=syncFields;
 q('#net-reset').onclick=()=>{clearReview();fillForm();error();message('Draft reset to the current demo profile.');};
 q('#net-settings-form').onsubmit=e=>{e.preventDefault();if(!editable())return;const checked=N.validateSettings(readDraft());for(const[field,id]of Object.entries(fields))q('#'+id).setAttribute('aria-invalid',Boolean(checked.errors[field]));if(!checked.valid){error(Object.values(checked.errors).join('\n'));q('#'+fields[Object.keys(checked.errors)[0]])?.focus();return;}error();const changes=N.changes(snapshot.profile,checked.value);if(!changes.length){message('No changes to apply.');return;}reviewDraft=checked.value;const box=q('#net-diff');box.replaceChildren();for(const c of changes){const row=node('div');row.className='net-diff-row';row.append(node('span',c.label+' / '+format(c.before)),node('b',format(c.after)));box.append(row);}q('#net-settings-form').hidden=true;q('#net-review').hidden=false;};
 q('#net-review-cancel').onclick=clearReview;
 q('#net-apply').onclick=()=>{if(!reviewDraft)return;try{const applied=adapter.apply(selected,reviewDraft);snapshot=applied.snapshot;checkpoint={id:selected,before:applied.previous,remaining:15};q('#net-review').hidden=true;q('#net-checkpoint').hidden=false;q('#net-countdown').textContent='15';reviewDraft=null;syncSummary();syncFields();revertTimer=setInterval(()=>{if(!checkpoint)return;checkpoint.remaining--;q('#net-countdown').textContent=checkpoint.remaining;if(checkpoint.remaining<=0)rollback('Confirmation timed out. Previous demo settings restored.');},1000);message('Demo profile applied. Keep it or let it revert.');}catch(e){error(e.message);}};
 q('#net-keep').onclick=()=>{clearInterval(revertTimer);revertTimer=null;checkpoint=null;q('#net-checkpoint').hidden=true;q('#net-settings-form').hidden=false;render();message('Demo settings kept for this session.');};q('#net-revert').onclick=()=>rollback();
 document.addEventListener('visibilitychange',()=>{if(document.hidden){stopPoll();rollback('Unconfirmed changes reverted when the preview was hidden.');wipeSecret();cancelOperation();}else if(open)startPoll();});
 const api={
  open(from){open=true;snapshot=adapter.snapshot();selected=snapshot.active||selected;wipeSecret();resetArm();clearReview();error();message();setTab('overview');render();show(from);startPoll();},
  onClose(){open=false;stopPoll();rollback();cancelOperation();wipeSecret();resetArm();clearReview();},
  setMode(next){if(mode===next)return;mode=next;if(open)startPoll();},
  syncSummary(){snapshot=adapter.snapshot();syncSummary();}
 };
 return api;
};
